#!/bin/sh
# Regenerates src/icons.ts from the icon names used in the source, so the bundle only carries those.
names=$( (grep -ohE "icon: '[A-Za-z0-9]+'" src/*.ts src/*.tsx | sed -E "s/icon: '(.*)'/\1/"; grep -ohE "name=\"[A-Za-z0-9]+\"" src/*.tsx | sed -E 's/name="(.*)"/\1/'; grep -ohE "\['[A-Z][A-Za-z0-9]+', '" src/extras.tsx | sed -E "s/\['(.*)', '/\1/"; grep -ohE "name=\{[^}]*\}" src/*.tsx | grep -oE "'[A-Z][A-Za-z0-9]+'" | tr -d "'"; printf 'Circle\n') | sort -u | paste -sd, | sed 's/,/, /g')
cat > src/icons.ts <<EOT
// Generated by scripts-icons.sh: only the icons the app uses, so the bundle does not carry the whole set.
import { $names } from 'lucide-react'

export const icons: Record<string, typeof Circle> = { $names }
EOT
